def setup():
 d=Document();sec=d.sections[0];sec.page_width=Cm(21);sec.page_height=Cm(29.7)
 sec.top_margin=Cm(2);sec.bottom_margin=Cm(2);sec.left_margin=Cm(2.5);sec.right_margin=Cm(1.7)
 sec.header_distance=Cm(.8);sec.footer_distance=Cm(.8)
 for name in ['Normal','Title','Subtitle','Heading 1','Heading 2','Heading 3']:
  s=d.styles[name];s.font.name='Times New Roman';s.font.color.rgb=RGBColor(0,0,0)
  s.paragraph_format.space_after=Pt(6)
  for border in s.element.xpath('.//w:pBdr'):border.getparent().remove(border)
  rf=s.element.get_or_add_rPr().rFonts
  if rf is not None:
   for attr in list(rf.attrib):
    if 'Theme' in attr or 'theme' in attr:del rf.attrib[attr]
 d.styles['Normal'].font.size=Pt(13)
 d.styles['Normal'].paragraph_format.line_spacing=1.08
 d.styles['Normal'].paragraph_format.first_line_indent=Cm(.7)
 for name,size in [('Title',20),('Heading 1',17),('Heading 2',14)]:
  d.styles[name].font.size=Pt(size);d.styles[name].font.bold=True
  d.styles[name].paragraph_format.first_line_indent=Cm(0)
 sec.different_first_page_header_footer=True
 footer=sec.footer.paragraphs[0];footer.alignment=WD_ALIGN_PARAGRAPH.CENTER
 fld=OxmlElement('w:fldSimple');fld.set(qn('w:instr'),'PAGE');footer._p.append(fld)
 d.core_properties.title='Цифровой двойник БПЛА ВТ 440';d.core_properties.author='Проектная группа МАИ'
 return d

def p(text,bold=False,italic=False):
 a=d.add_paragraph();a.alignment=WD_ALIGN_PARAGRAPH.JUSTIFY
 run=a.add_run(text);run.bold=bold;run.italic=italic
 return a

def h(text,level=1):d.add_heading(text,level)
def page(title):
 a=d.add_heading(title,1);a.paragraph_format.page_break_before=True
def eq(text):
 a=d.add_paragraph();a.alignment=WD_ALIGN_PARAGRAPH.CENTER;a.paragraph_format.first_line_indent=Cm(0)
 m=OxmlElement('m:oMath')
 sub=dict(zip('₀₁₂₃₄₅₆₇₈₉ₖ₊₋ᵢ','0123456789k+-i'))
 sup=dict(zip('⁰¹²³⁴⁵⁶⁷⁸⁹ᵇᵀⁿ⁻ᵘ','0123456789bTn-u'))
 def mr(value):
  r=OxmlElement('m:r');t=OxmlElement('m:t');t.set(qn('xml:space'),'preserve');t.text=value;r.append(t);return r
 buf='';i=0
 while i<len(text):
  chars=sub if text[i] in sub else (sup if text[i] in sup else None)
  if chars is None:buf+=text[i];i+=1;continue
  base=buf[-1:] if buf else '';buf=buf[:-1]
  if buf:m.append(mr(buf))
  buf='';index=''
  while i<len(text) and text[i] in chars:index+=chars[text[i]];i+=1
  node=OxmlElement('m:sSub' if chars is sub else 'm:sSup');e=OxmlElement('m:e')
  if base:e.append(mr(base))
  elif len(m):e.append(m[-1])
  node.append(e);idx=OxmlElement('m:sub' if chars is sub else 'm:sup');idx.append(mr(index));node.append(idx);m.append(node)
 if buf:m.append(mr(buf))
 a._p.append(m)

def table(headers,rows,widths=None,size=10.5):
 t=d.add_table(rows=1,cols=len(headers));t.alignment=WD_TABLE_ALIGNMENT.CENTER;t.autofit=False
 if widths:
  for column,w in zip(t.columns,widths):column.width=Cm(w)
  for cell,w in zip(t.rows[0].cells,widths):cell.width=Cm(w)
 for i,x in enumerate(headers):t.rows[0].cells[i].text=str(x)
 for row in rows:
  cells=t.add_row().cells
  for i,x in enumerate(row):cells[i].text=str(x)
 for ri,row in enumerate(t.rows):
  if widths:
   for cell,w in zip(row.cells,widths):cell.width=Cm(w)
  trPr=row._tr.get_or_add_trPr();no=OxmlElement('w:cantSplit');trPr.append(no)
  if ri==0:
   repeat=OxmlElement('w:tblHeader');trPr.append(repeat)
  for ci,cell in enumerate(row.cells):
   cell.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
   tcPr=cell._tc.get_or_add_tcPr();shade=OxmlElement('w:shd');shade.set(qn('w:fill'),'17334B' if ri==0 else ('F0F4F7' if ri%2==0 else 'FFFFFF'));tcPr.append(shade)
   borders=OxmlElement('w:tcBorders')
   for side in ['top','left','bottom','right']:
    e=OxmlElement('w:'+side);e.set(qn('w:val'),'single');e.set(qn('w:sz'),'4');e.set(qn('w:color'),'D9D9D9');borders.append(e)
   tcPr.append(borders);marg=OxmlElement('w:tcMar')
   for side in ['top','left','bottom','right']:
    e=OxmlElement('w:'+side);e.set(qn('w:w'),'85');e.set(qn('w:type'),'dxa');marg.append(e)
   tcPr.append(marg)
   for para in cell.paragraphs:
    para.paragraph_format.first_line_indent=Cm(0);para.paragraph_format.space_after=Pt(2);para.paragraph_format.space_before=Pt(2);para.paragraph_format.line_spacing=1.02
    for run in para.runs:run.font.size=Pt(size);run.bold=ri==0;run.font.color.rgb=RGBColor.from_string('FFFFFF' if ri==0 else '000000')
 return t

